items.signature:
anna.audio.session(config: {llm?: 'agent'|'none', submode?: 'auto'|'fixed', fixed_client_id?: string, voice?: string, language?: string, speed?: number, context?: string, system?: string, maxDurationSec?: number}) => Promise<VoiceSession>

VoiceSession {
  sessionId: string; audioConfig: {format:'pcm', sample_rate:24000, channels:1, bits_per_sample:16}; models: {asr, tts, voice}; maxDurationSec: number; asrIdleTimeoutSec: number|null;
  sendAudio(pcm16: Int16Array|ArrayBuffer|Uint8Array): number;   // 16 kHz mono; auto-chunked ≤32 KB; fire-and-forget
  flushAudio(): void;                                           // push-to-talk released → finalize the pending sentence now
  setContext(text: string): Promise<void>;                      // ≤4 KB, replace semantics, applies from the next utterance
  say(text: string, opts?: {priority?: 'normal'|'high', interrupt?: boolean, sayId?: string}): Promise<{sayId: string}>;  // ≤1000 chars, TTS-only
  interrupt(): Promise<void>;
  end(): Promise<{duration, total_asr_seconds, total_tts_characters, reason}>;
  on(event, handler): () => void;  off(event, handler): void;   // event '*' receives (event, payload)
}

