const mic = anna.audio.mic({ sampleRate: 16000, onChunk: (pcm16) => { if (talking) vs.sendAudio(pcm16); } });
await mic.start();            // prompts for the microphone (iframe gets allow="microphone" from host_api.audio ∋ 'session')
mic.setMuted(true);           // push-to-talk gate

const vs = await anna.audio.session({ llm: 'agent', language: 'zh', system: 'Answer in one short sentence.', maxDurationSec: 1800 });
const player = anna.audio.player({ sampleRate: vs.audioConfig.sample_rate });

vs.on('asr_final',  ({ text })  => transcript.append(text));
vs.on('llm_partial',({ text })  => reply.textContent += text);
vs.on('tts_audio',  ({ audio }) => player.enqueue(audio));
vs.on('tts_done',   ()          => player.flush());
vs.on('interrupted',()          => player.stop());          // barge-in
vs.on('ended',      (usage)     => console.log(usage.total_asr_seconds, usage.total_tts_characters));

ptt.onpointerdown = () => { talking = true;  mic.setMuted(false); };
ptt.onpointerup   = () => { talking = false; mic.setMuted(true); vs.flushAudio(); };

setInterval(() => vs.setContext(JSON.stringify(gameState)), 1000);   // ≤4 KB, replaces, next turn
await vs.say('Careful, top lane.', { priority: 'high' });            // TTS-only, preempts

anna.on('host.app_state', ({ state }) => { if (state !== 'active') vs.end(); });  // mobile: foreground-only
await vs.end();

const mic = anna.audio.mic({ onChunk: (pcm16) => talking && vs.sendAudio(pcm16), onLevel: (rms) => vu.style.width = `${Math.min(100, rms * 400)}%` });
await mic.start();
mic.setMuted(true);   // emit nothing until the user presses the button

const player = anna.audio.player({ sampleRate: vs.audioConfig.sample_rate });
vs.on('tts_audio',   ({ audio }) => player.enqueue(audio));
vs.on('tts_done',    () => player.flush());
vs.on('interrupted', () => player.stop());
vs.on('ended',       () => player.destroy());
